policies.inbound:




    %%AUDIENCE_ELEMENTS%%


    %%ISSUER_V1%%
    %%ISSUER_V2%%



      %%TENANT_ID%%




















        application/json


        no-store


        @(context.RequestId.ToString())

      @(new JObject(new JProperty("type", "error"), new JProperty("error", new JObject(new JProperty("type", "permission_error"), new JProperty("message", "This token cannot read usage from this gateway. Sign in with the gateway's client and try again. Request id: " + context.RequestId.ToString() + ".")))).ToString(Newtonsoft.Json.Formatting.None))









      %%RESOLVER_USAGE_URL%%
      POST

        application/json


        @("Bearer " + (string)context.Variables["ccofResolverToken"])

      @(new JObject(new JProperty("personId", (string)context.Variables["ccofOid"]), new JProperty("requestId", context.RequestId.ToString())).ToString(Newtonsoft.Json.Formatting.None))





<set-variable name="ccofUsageBody" value="@{
    var response = context.Variables.ContainsKey("ccofUsageResponse") ? context.Variables["ccofUsageResponse"] as IResponse : null;
    if (response == null || response.StatusCode != 200) { return ""; }
    try {
        var body = response.Body.As();
        return body != null && body["schema"] != null && body["schema"].Type == JTokenType.String && (string)body["schema"] == "ccof.usage.v1" && body["scopes"] is JArray
            ? body.ToString(Newtonsoft.Json.Formatting.None) : "";
    } catch {
        return "";
    }
}" />





        application/json


        no-store


        @(context.RequestId.ToString())

      @((string)context.Variables["ccofUsageBody"])






        %%RETRY_AFTER%%


        application/json


        no-store


        @(context.RequestId.ToString())

      @(new JObject(new JProperty("type", "error"), new JProperty("error", new JObject(new JProperty("type", "api_error"), new JProperty("message", "Usage figures are temporarily unavailable. Your access to Claude is not affected. Retry in %%RETRY_AFTER%% seconds. Request id: " + context.RequestId.ToString() + ".")))).ToString(Newtonsoft.Json.Formatting.None))
